  "dependencies": {"next": "^16.0.0", "react": "^19.0.0", "react-dom": "^19.0.0", "neatlogs": "latest", "zod": "^4.0.0", "pdfjs-dist": "^4.10.38"},
  "devDependencies": {"@types/node": "^22.0.0", "@types/react": "^19.0.0", "@types/react-dom": "^19.0.0", "eslint": "^9.0.0", "eslint-config-next": "^16.0.0", "typescript": "^5.0.0", "tsx": "^4.0.0"}
}
import { z } from "zod";

const itemId = z.string().min(1).max(100);
const money = z.number().finite().nonnegative();
const quantity = z.number().finite().positive();
const currency = z.literal("INR");
const date = z.iso.date();

export const contractSchema = z.object({
  type: z.literal("contract"), id: itemId, supplierId: itemId,
  currency, validFrom: date, validTo: date.optional(),
  prices: z.array(z.object({ sku: itemId, unitPrice: money })).min(1),
  evidence: z.string().min(1)
}).strict();
export const purchaseOrderSchema = z.object({
  type: z.literal("purchase_order"), id: itemId, supplierId: itemId,
  contractId: itemId, currency, orderedAt: date,
  items: z.array(z.object({ sku: itemId, quantity, unitPrice: money })).min(1)
}).strict();
export const invoiceSchema = z.object({
  type: z.literal("invoice"), id: itemId, supplierId: itemId,
  purchaseOrderId: itemId, currency, issuedAt: date,
  items: z.array(z.object({ sku: itemId, quantity, unitPrice: money })).min(1)
}).strict();
export const auditInputSchema = z.object({
  contract: contractSchema,
  purchaseOrder: purchaseOrderSchema,
  invoices: z.array(invoiceSchema).min(1).max(25)
}).strict();
export type AuditInput = z.infer<typeof auditInputSchema>;
export type Finding = {
  invoiceId: string; sku: string; status: "potential_overcharge" | "needs_review";
  expectedUnitPrice?: number; billedUnitPrice: number; quantity: number;
  potentialOvercharge?: number; reason: string; evidence: string[];
};
export type AuditResult = { status: "completed" | "needs_review"; currency: "INR"; totalPotentialOvercharge: number; findings: Finding[]; checkedInvoices: number; warnings: string[] };
import { auditInputSchema, type AuditInput, type AuditResult, type Finding } from "./schema";

// Money is calculated in integer paise to avoid floating point accumulation.
const paise = (n: number) => Math.round(n * 100);
const rupees = (n: number) => Number((n / 100).toFixed(2));
const uniqueBySku = <T extends { sku: string }>(xs: T[]) => new Map(xs.map(x => [x.sku, x]));
const hasRepeatedSku = <T extends { sku: string }>(xs: T[]) => new Set(xs.map(x => x.sku)).size !== xs.length;

export function auditDocuments(untrusted: unknown): AuditResult {
  const data: AuditInput = auditInputSchema.parse(untrusted);
  const { contract, purchaseOrder: po, invoices } = data;
  const warnings: string[] = [];
  const findings: Finding[] = [];
  let totalPaise = 0;

  if (contract.supplierId !== po.supplierId || contract.id !== po.contractId) {
    throw new Error("Contract and purchase order do not match");
  }
  if (hasRepeatedSku(contract.prices) || hasRepeatedSku(po.items)) {
    throw new Error("Repeated SKU in contract or purchase order; manual review required");
  }
  const contractPrices = uniqueBySku(contract.prices);
  const poPrices = uniqueBySku(po.items);
  const seenInvoices = new Set<string>();

  for (const invoice of invoices) {
    if (invoice.supplierId !== contract.supplierId || invoice.purchaseOrderId !== po.id) {
      warnings.push(`${invoice.id}: supplier or PO mismatch; not audited`);
      continue;
    }
    if (seenInvoices.has(invoice.id)) {
      warnings.push(`${invoice.id}: duplicate invoice ID in upload; requires human review`);
      continue;
    }
    seenInvoices.add(invoice.id);
    if (hasRepeatedSku(invoice.items)) {
      warnings.push(`${invoice.id}: repeated SKU lines; requires human review`);
      continue;
    }
    if (invoice.issuedAt < contract.validFrom || (contract.validTo && invoice.issuedAt > contract.validTo)) {
      warnings.push(`${invoice.id}: invoice date outside contract validity; requires amendment review`);
      continue;
    }
    for (const line of invoice.items) {
      const contracted = contractPrices.get(line.sku);
      const ordered = poPrices.get(line.sku);
      const evidence = [`Contract ${contract.id}: ${contract.evidence}`, `Purchase order ${po.id}`, `Invoice ${invoice.id}: item ${line.sku}`];
      if (!contracted || !ordered) {
        findings.push({ invoiceId: invoice.id, sku: line.sku, status: "needs_review", billedUnitPrice: line.unitPrice, quantity: line.quantity, reason: "No matching SKU in both contract and PO", evidence });
        continue;
      }
      if (paise(ordered.unitPrice) !== paise(contracted.unitPrice) || line.quantity > ordered.quantity) {
        findings.push({ invoiceId: invoice.id, sku: line.sku, status: "needs_review", billedUnitPrice: line.unitPrice, quantity: line.quantity, reason: "PO price differs from contract or billed quantity exceeds ordered quantity", evidence });
        continue;
      }
      const delta = paise(line.unitPrice) - paise(contracted.unitPrice);
      if (delta > 0) {
        // Assumes quantity is integral or a quantity where multiplication remains in paise.
        const overcharge = Math.round(delta * line.quantity);
        totalPaise += overcharge;
        findings.push({ invoiceId: invoice.id, sku: line.sku, status: "potential_overcharge", expectedUnitPrice: contracted.unitPrice, billedUnitPrice: line.unitPrice, quantity: line.quantity, potentialOvercharge: rupees(overcharge), reason: "Billed unit price exceeds valid agreed unit price (tax/freight excluded)", evidence });
      }
    }
  }
  return { status: warnings.length || findings.some(f => f.status === "needs_review") ? "needs_review" : "completed", currency: "INR", totalPotentialOvercharge: rupees(totalPaise), findings, checkedInvoices: seenInvoices.size, warnings };
}
/** PDF text extraction only. Extracted text is untrusted and must be reviewed/mapped
 * into the existing JSON schema before it can enter the deterministic audit flow.
 */
export type PdfPageText = { page: number; text: string };

const MAX_PDF_BYTES = 10 * 1024 * 1024;
const MAX_PDF_PAGES = 250;

export async function extractPdfPages(input: Uint8Array): Promise<PdfPageText[]> {
  if (input.byteLength === 0) throw new Error("PDF is empty");
  if (input.byteLength > MAX_PDF_BYTES) throw new Error("PDF exceeds the 10MB limit");
  if (new TextDecoder().decode(input.subarray(0, 5)) !== "%PDF-") {
    throw new Error("Uploaded file is not a PDF");
  }

  const pdfjs = await import("pdfjs-dist/legacy/build/pdf.mjs");
  const loadingTask = pdfjs.getDocument({ data: new Uint8Array(input) });
  const document = await loadingTask.promise;
  if (document.numPages > MAX_PDF_PAGES) {
    await loadingTask.destroy();
    throw new Error("PDF exceeds the 250 page limit");
  }
  const pages: PdfPageText[] = [];
  try {
    for (let pageNumber = 1; pageNumber <= document.numPages; pageNumber++) {
      const page = await document.getPage(pageNumber);
      const content = await page.getTextContent();
      const text = content.items
        .filter((item): item is typeof item & { str: string } => "str" in item)
        .map(item => item.str)
        .join(" ")
        .replace(/\s+/g, " ")
        .trim();
      pages.push({ page: pageNumber, text });
      page.cleanup();
    }
  } finally {
    await loadingTask.destroy();
  }
  return pages;
}
import { init, flush, span } from "neatlogs";
let initialization: Promise<void> | undefined;
export async function ensureTracing() {
  if (!process.env.NEATLOGS_API_KEY) return false;
  initialization ??= init({ apiKey: process.env.NEATLOGS_API_KEY, workflowName: "supplier-invoice-audit" });
  await initialization;
  return true;
}
// Privacy: capture neither inputs nor outputs (supplier financial information).
export const tracedParse = span({ kind: "TOOL", name: "validate_supplier_documents", captureInput: false, captureOutput: false }, async <T>(fn: () => T) => fn());
export const tracedAudit = span({ kind: "CHAIN", name: "compare_contract_and_invoice", captureInput: false, captureOutput: false }, async <T>(fn: () => T) => fn());
export const tracedWorkflow = span({ kind: "WORKFLOW", name: "supplier_invoice_audit", captureInput: false, captureOutput: false }, async <T>(fn: () => Promise<T>) => fn());
export async function flushTracing(enabled: boolean) { if (enabled) await flush(); }
import { NextResponse } from "next/server";
import { extractPdfPages } from "@/lib/pdf-ingestion";

export const runtime = "nodejs";
const MAX_PDF_BYTES = 10 * 1024 * 1024;

export async function POST(request: Request) {
  try {
    const form = await request.formData();
    const file = form.get("file");
    if (!(file instanceof File)) {
      return NextResponse.json({ error: "Upload a PDF in the 'file' field" }, { status: 400 });
    }
    if (file.size > MAX_PDF_BYTES) {
      return NextResponse.json({ error: "PDF exceeds the 10MB limit" }, { status: 413 });
    }
    if (file.type && file.type !== "application/pdf") {
      return NextResponse.json({ error: "File must have PDF content type" }, { status: 415 });
    }
    const pages = await extractPdfPages(new Uint8Array(await file.arrayBuffer()));
    return NextResponse.json({ pages });
  } catch (error) {
  const message =
    error instanceof Error ? error.message : "PDF ingestion failed";

  if (process.env.NODE_ENV === "development") {
    console.error("[PDF DEBUG]", {
      name: error instanceof Error ? error.name : typeof error,
      message,
    });
  }

  const clientError = /empty|limit|not a PDF/i.test(message);

  return NextResponse.json(
    { error: clientError ? message : "PDF could not be read" },
    { status: clientError ? 400 : 422 }
  );
  }
}
import { NextResponse } from "next/server";
import { z } from "zod";
import { auditInputSchema } from "@/lib/schema";
import { auditDocuments } from "@/lib/audit";
import { ensureTracing, tracedParse, tracedAudit, tracedWorkflow, flushTracing } from "@/lib/observability";
export const runtime = "nodejs";
export async function POST(request: Request) {
  let tracing = false;
  try {
    if (Number(request.headers.get("content-length") || 0) > 1024 * 1024) {
      return NextResponse.json({ error: "Payload too large; 1MB maximum" }, { status: 413 });
    }
    tracing = await ensureTracing();
    const payload = await request.json();
    const result = await tracedWorkflow(async () => {
      const validated = await tracedParse(() => auditInputSchema.parse(payload));
      return tracedAudit(() => auditDocuments(validated));
    });
